INSERT INTO `categories` VALUES (1,1,'Visiting Cards','visiting-cards','Premium business & visiting cards with multiple finishes','/uploads/category-1785004426238-772570326.jpg',NULL,1,6,NULL,NULL,'2026-02-28 17:14:57','2026-08-01 17:19:57'),(2,1,'ID Cards & Lanyards','id-cards-and-lanyards','Custom ID cards, holders & lanyard printing','/uploads/category-1785004732831-528239823.jpg',NULL,1,2,NULL,NULL,'2026-02-28 17:14:57','2026-07-25 18:38:54'),(11,1,'Tray  Set','tray-set','**Wooden Serving Tray Set of 3 with Gold Engraving | Royal Camel Design**\n\nAdd a touch of royal elegance to your home with this premium **Wooden Serving Tray Set of 3**, beautifully crafted with an intricate **Royal Camel Gold Engraving** design. Made from high-quality wood, these trays combine durability with timeless style, making them perfect for serving tea, coffee, snacks, desserts, or festive treats.\n\nThe luxurious gold-engraved camel artwork brings a traditional royal charm, making this tray set ideal for everyday use as well as special occasions. Lightweight yet sturdy, the trays feature smooth edges for comfortable handling and are easy to clean.\n\nWhether you\'re entertaining guests or looking for a thoughtful gift, this elegant serving tray set is a perfect choice for housewarmings, weddings, festivals, and corporate gifting.\n\n**Features:**\n\n* Premium quality wooden construction\n* Set of 3 serving trays in different sizes\n* Elegant Royal Camel gold engraving\n* Smooth finish with durable craftsmanship\n* Perfect for serving tea, coffee, snacks, and desserts\n* Ideal for home décor, gifting, and festive occasions\n* Easy to clean and maintain\n','/uploads/category-1785602084242-11987627.jpg',NULL,1,3,NULL,NULL,'2026-08-01 16:33:08','2026-08-01 17:19:22'),(12,1,'Glossy Visiting Cards','glossy-visiting-cards','Vistaprint India customizes all its products in facilities located within India. Some of our raw materials, intermediate components, and consumables used in the manufacturing of the final product could be from one or more countries. As we follow Global Sourcing, one product is likely to have a different country of origin depending on the batch sold','/uploads/category-1785606353067-670243530.jpg',NULL,1,4,NULL,NULL,'2026-08-01 17:45:56','2026-08-01 17:45:56');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;

