INSERT INTO `products` VALUES (26,1,'Wooden Serving Tray Set of 3 with Gold Engraving | Royal Camel Design | Waterproof Enamel Coated Decorative Trays | Rectangular, 16X10, 14X8, 12X6 (Royal Camel)','wooden-serving-tray-set-of-3-with-gold-engraving-or-royal-camel-design-or-waterproof-enamel-coated-decorative-trays-or-rectangular-16x10-14x8-12x6-royal-camel','Tray_001','<ul>\n    <li>\n        <h2>Wooden Serving Tray with Gold Engraving | Set of 3 | Royal Camel Design Elevate your home decor and serving style with our exquisite Set of 3 Wooden Serving Trays, featuring intricate gold engraving and a captivating Royal Camel design. These decorative trays are not just visually stunning; they are also highly practical and built for durability. Crafted from premium quality wood, each tray in this collection boasts a meticulously applied enamel coating, rendering them completely waterproof and incredibly easy to maintain. Spills are no match for these trays, ensuring effortless cleanup. The classic rectangular shape of these versatile trays makes them perfect for a multitude of uses – from presenting delicious appetizers and beverages to organizing your everyday essentials or beautifully displaying your cherished decor pieces. This comprehensive set includes three convenient sizes to cater to all your entertaining and styling needs: a grand 16 x 10 inch, a practical 14 x 8 inch, and a charming 12 x 6 inch. Whether you\'re hosting a lavish dinner party, enjoying a tranquil breakfast in bed, or simply infusing a touch of regal sophistication into your living space, these wooden trays are the ideal choice.<br></h2>\n    </li>\n    <hr>\n    <hr>\n    <h2><br></h2>\n</ul>','<table class=\"a-normal a-spacing-micro\" role=\"list\"><tbody><tr class=\"a-spacing-small po-brand\" role=\"listitem\"><td class=\"a-span3\" role=\"presentation\">Brand</td><td class=\"a-span9\" role=\"presentation\">SK Prints</td></tr><tr class=\"a-spacing-small po-color\" role=\"listitem\"><td class=\"a-